// Service worker Demo Studio app — generated by Serwist + Web Push handler
// See: https://serwist.pages.dev/docs/next/getting-started

import { defaultCache } from '@serwist/next/worker'
import type { PrecacheEntry, SerwistGlobalConfig } from 'serwist'
import { Serwist } from 'serwist'

declare global {
  interface WorkerGlobalScope extends SerwistGlobalConfig {
    __SW_MANIFEST: (PrecacheEntry | string)[] | undefined
  }
}

declare const self: ServiceWorkerGlobalScope

const serwist = new Serwist({
  precacheEntries: self.__SW_MANIFEST,
  skipWaiting: true,
  clientsClaim: true,
  navigationPreload: true,
  runtimeCaching: defaultCache,
  fallbacks: {
    entries: [
      {
        url: '/offline',
        matcher({ request }) {
          return request.destination === 'document'
        },
      },
    ],
  },
})

serwist.addEventListeners()

// =============================================================================
// Web Push handler — notificaciones de Demo Studio (lista de espera, broadcast,
// recordatorios). Payload acordado con Edge Function `send-push-notification`:
// { title: string, body: string, url?: string, tag?: string, icon?: string }
// =============================================================================

self.addEventListener('push', (event: PushEvent) => {
  if (!event.data) return

  let data: { title?: string; body?: string; url?: string; tag?: string; icon?: string } = {}
  try {
    data = event.data.json()
  } catch {
    data = { title: 'Demo Studio', body: event.data.text() }
  }

  const title = data.title ?? 'Demo Studio'
  const options: NotificationOptions = {
    body: data.body ?? '',
    icon: data.icon ?? '/icon-192.png',
    badge: '/icon-192.png',
    tag: data.tag,
    data: { url: data.url ?? '/' },
  }

  event.waitUntil(self.registration.showNotification(title, options))
})

self.addEventListener('notificationclick', (event: NotificationEvent) => {
  event.notification.close()
  const targetUrl = (event.notification.data as { url?: string })?.url ?? '/'

  event.waitUntil(
    self.clients
      .matchAll({ type: 'window', includeUncontrolled: true })
      .then((windowClients) => {
        // Si ya hay una pestaña abierta de la app, focus + navigate
        const existing = windowClients.find((c) => c.url.includes(self.registration.scope))
        if (existing) {
          existing.focus()
          if ('navigate' in existing) {
            return (existing as WindowClient).navigate(targetUrl)
          }
        }
        return self.clients.openWindow(targetUrl)
      })
  )
})
